struct XformedVertex {
    float x, y, z, rhw;
}; /* the transformed buffer, FVF XYZRHW */
struct FlatVertex {
    float x, y, z, rhw;
    u32 diffuse, specular;
}; /* FVF 0xc4 */
struct TexVertex {
    float x, y, z, rhw;
    u32 diffuse, specular;
    float u, v;
}; /* FVF 0x1c4 */
struct D3DXyzrhwVertex { /* a D3DFVF_XYZRHW vertex, as ProcessVertices writes it (the outlined draws) */
    float x, y, z, rhw;
};
struct FlameVertex { /* a D3DTLVERTEX (FVF 0x1c4), the vertex of a textured RenderPoly (the outlined draws) */
    float x, y, z, rhw;
    u32 diffuse, specular;
    float u, v;
};
/* the vertex format SubmitPoly indexes its textured batches with */
struct TlVertexTex {
    float x, y, z, rhw;
    u32 diffuse, specular;
    float u, v;
    TlVertexTex() {}
};
class
    Texture; /* class, as sdw_classes.h has it: a `struct` key here would mangle the out-of-line Render_SetTexture call as PAUTexture, a name no object defines */

