#define SDW_MEMBERS_Frustrum                                      \
    __forceinline u32 FogAt(float z)                              \
    {                                                             \
        if (fogEnabled == 1) {                                    \
            if (z < fogStart)                                     \
                return 0xff000000;                                \
            if (z > fogEnd)                                       \
                return 0;                                         \
            s32 idx = (s32)((z - fogStart) * fogScale);           \
            return fogRamp[idx];                                  \
        }                                                         \
        return 0xff000000;                                        \
    }                                                             \
    u32 FogColor(float depth)                                     \
    {                                                             \
        if (fogEnabled == 1) {                                    \
            if (depth < fogStart)                                 \
                return 0xff000000;                                \
            else if (depth > fogEnd)                              \
                return 0;                                         \
            else {                                                \
                s32 index = (s32)((depth - fogStart) * fogScale); \
                return fogRamp[index];                            \
            }                                                     \
        } else                                                    \
            return 0xff000000;                                    \
    }
