    void SubmitPolyTinted(RenderPoly *poly);                                                   \
    void SubmitPolyCalls(RenderPoly *);                                                        \
    void SubmitPolyInlineSet(RenderPoly *);                                                    \
    void SubmitPolyInlineClear(RenderPoly *);
